// Validamos que el backend responda con éxito (Código 200)
pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

// Validamos que la respuesta nos devuelva el Token JWT
pm.test("Devuelve un token JWT", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property('token'); 
    // Nota: Si tu API devuelve el token con otro nombre (ej. accessToken), cambia 'token' por ese nombre.
});

// Validamos que el backend devuelva un error de no autorizado (Código 401)
pm.test("Status code es 401", function () {
    pm.response.to.have.status(401);
});

// Validamos que el backend devuelva un mensaje explicando el error
pm.test("Mensaje de credenciales incorrectas", function () {
    var jsonData = pm.response.json();
    
    // Verifica si la respuesta contiene un mensaje de error. 
    // Nota: Si tu backend devuelve el error en otra propiedad (ej: jsonData.error), cambia '.message' por esa propiedad.
    pm.expect(jsonData.message).to.be.a('string');
});
